INSERT INTO content (id, type, title, body, isPublished, createdAt) VALUES
(UUID(), 'NOTICE_INTERNAL', '2024년 하반기 전사 워크샵 안내', '안녕하세요. 인사팀입니다.\n\n2024년 하반기 전사 워크샵을 다음과 같이 안내드립니다.\n\n일시: 2024년 11월 15일(금) ~ 16일(토)\n장소: 강원도 평창 리조트\n참석 대상: 전 임직원\n\n참석 여부를 11월 1일까지 인사팀으로 회신 부탁드립니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '사내 네트워크 점검 공지', 'IT 인프라팀에서 안내드립니다.\n\n아래 일정으로 사내 네트워크 정기 점검을 실시합니다.\n\n점검 일시: 2024년 10월 26일(토) 00:00 ~ 06:00\n영향 범위: 사내 Wi-Fi, 사내망, 전산 시스템 전체\n\n해당 시간 중 업무 시스템 접속이 불가하오니 참고 바랍니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '연차 사용 촉진 안내', '인사팀에서 안내드립니다.\n\n근로기준법에 따라 미사용 연차에 대한 사용 촉진을 안내드립니다.\n잔여 연차는 개인별 인사 시스템에서 확인하시고, 12월 31일 이전 소진 바랍니다.\n\n문의: 인사팀 내선 100', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '복지포인트 지급 안내', '인사팀에서 안내드립니다.\n\n2024년 하반기 복지포인트가 지급되었습니다.\n\n지급 금액: 직급별 차등 지급 (상세 내용은 인사 시스템 참조)\n사용 기간: 2024년 10월 1일 ~ 2025년 3월 31일\n사용 처: 제휴 복지몰, 건강검진, 자기계발비 등\n\n복지포인트 사용 관련 문의는 인사팀으로 연락 바랍니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '사내 동호회 모집 공고', '복지 담당팀에서 안내드립니다.\n\n아래 동호회의 신규 회원을 모집합니다.\n\n- 독서 모임: 월 1회 독서 토론\n- 러닝 클럽: 주 1회 퇴근 후 한강 러닝\n- 보드게임 클럽: 격주 금요일 오후\n- 등산 모임: 월 1회 주말 등산\n\n신청: 사내 그룹웨어 > 동호회 신청', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '보안 교육 이수 의무 안내', '정보보안팀에서 안내드립니다.\n\n전 임직원 대상 연간 정보보안 교육 이수가 의무화되었습니다.\n\n이수 기한: 2024년 11월 30일\n교육 방법: e-Learning 시스템 로그인 후 수강\n소요 시간: 약 2시간\n\n기한 내 미이수 시 인사고과에 반영될 수 있으니 반드시 이수 부탁드립니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '출퇴근 관련 업무 규정 개정 안내', '인사팀에서 안내드립니다.\n\n2024년 11월부터 아래와 같이 출퇴근 규정이 일부 개정됩니다.\n\n1. 유연근무제 신청 범위 확대 (오전 7시 ~ 10시 출근 선택 가능)\n2. 재택근무 주 최대 2일로 확대\n3. 초과근무 사전 승인제 도입\n\n자세한 내용은 인사팀 공유 드라이브를 참고하여 주시기 바랍니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '사내 식당 운영 시간 변경 안내', '총무팀에서 안내드립니다.\n\n10월부터 사내 식당 운영 시간이 아래와 같이 변경됩니다.\n\n조식: 07:30 ~ 09:00 (기존 08:00 ~ 09:00)\n중식: 11:30 ~ 13:30 (동일)\n석식: 18:00 ~ 19:30 (기존 18:30 ~ 20:00)\n\n변경된 운영 시간 참고 부탁드립니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '전 직원 건강검진 일정 안내', '인사팀에서 안내드립니다.\n\n2024년도 임직원 건강검진을 아래와 같이 실시합니다.\n\n대상: 전 임직원 (만 35세 이상 종합검진 대상)\n기간: 2024년 11월 ~ 12월\n장소: 협약 병원 (예약 후 방문)\n\n검진 예약은 건강검진 예약 시스템에서 진행하시고, 영수증은 인사팀에 제출 바랍니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '신규 전자결재 시스템 도입 안내', 'IT 인프라팀에서 안내드립니다.\n\n기존 종이 결재 방식에서 전자결재 시스템으로 전면 전환합니다.\n\n전환 일자: 2024년 11월 1일\n적용 문서: 모든 사내 결재 문서\n\n사용 방법은 10월 중 부서별 교육을 통해 안내드릴 예정입니다.\n문의: IT 인프라팀 내선 200', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '법인카드 사용 가이드라인 개정 안내', '재무팀에서 안내드립니다.\n\n법인카드 사용 가이드라인이 다음과 같이 개정되었습니다.\n\n1. 1회 사용 한도: 50만원 (기존 30만원)\n2. 영수증 제출 기한: 사용일 기준 7일 이내\n3. 명절 선물 구매 금지 항목 추가\n\n개정된 가이드라인 위반 시 경고 조치가 있을 수 있습니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', 'IT 장비 교체 신청 접수', 'IT 인프라팀에서 안내드립니다.\n\n노후 IT 장비(3년 이상) 교체 신청을 받습니다.\n\n신청 기간: 2024년 10월 14일 ~ 10월 31일\n신청 방법: IT 헬프데스크 시스템에서 신청\n교체 항목: 노트북, 모니터, 키보드, 마우스 등\n\n신청 후 검토를 거쳐 순차적으로 교체 진행됩니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '팀 빌딩 행사 참가 신청 안내', '복지 담당팀에서 안내드립니다.\n\n4분기 팀 빌딩 활동비 지원 프로그램을 안내드립니다.\n\n지원 금액: 팀당 최대 30만원\n신청 방법: 팀장이 인사팀으로 계획서 제출\n신청 기한: 2024년 10월 20일\n정산 기한: 활동일로부터 1개월 이내\n\n팀원들과 즐거운 시간 되시기 바랍니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '사내 도서관 도서 신청 안내', '총무팀에서 안내드립니다.\n\n사내 도서관 도서 추가 구매를 위한 희망 도서 신청을 받습니다.\n\n신청 방법: 사내 그룹웨어 > 총무팀 게시판에 도서명/저자/출판사 기재\n신청 기간: 10월 31일까지\n\n1인당 최대 3권까지 신청 가능하며, 검토 후 구매합니다.', 1, NOW()),
(UUID(), 'NOTICE_INTERNAL', '개인정보 보호 서약서 제출 요청', '법무팀에서 안내드립니다.\n\n개인정보 보호법 개정에 따라 전 임직원의 개인정보 보호 서약서 갱신 제출이 필요합니다.\n\n제출 기한: 2024년 10월 31일\n제출 방법: 법무팀 담당자에게 서명 후 제출\n\n기한 내 미제출 시 별도 안내가 있을 예정입니다.', 1, NOW());
INSERT INTO content (id, type, title, body, isPublished, createdAt) VALUES
(UUID(), 'NOTICE_PUBLIC', '이도윤 대표이사, XX대학교 대학원 보컬 전공 석사 학위 취득', '이도윤 대표이사가 XX대학교 대학원 실용음악과 보컬 전공에서 석사 학위를 취득했습니다.\n\n이번 학위는 동요 창작과 아동 발성 지도에 대한 이해를 높이기 위한 것으로, 재직 중 대학원 과정을 병행하며 취득한 성과입니다.\n\n이도윤 대표이사는 "아이들의 목소리에 더 가까이 다가가기 위해 공부를 시작했다"며 소감을 전했습니다.', 1, NOW()),
(UUID(), 'NOTICE_PUBLIC', '이도윤 대표이사, XX대학교 대학원 보컬 전공 박사 학위 취득', '이도윤 대표이사가 XX대학교 대학원에서 보컬 전공 박사 학위를 취득했습니다.\n\n박사 학위 논문은 아동 발달 단계에 따른 발성 지도법을 주제로 하였으며, 이는 향후 JuniMusic의 동요 제작 및 아동 보컬 교육 콘텐츠에 반영될 예정입니다.\n\n당사는 이번 학위 취득을 계기로 음악 교육 분야와의 협업을 더욱 확대해 나갈 계획입니다.', 1, NOW()),
(UUID(), 'NOTICE_PUBLIC', '이도윤 대표이사, XX대학교 보컬전공 겸임교수 취임', '이도윤 대표이사가 XX대학교 실용음악과 보컬전공 겸임교수로 취임했습니다.\n\n이도윤 교수는 이번 학기부터 아동 보컬 지도법 강의를 맡아 후학 양성에도 힘쓸 예정입니다.\n\n당사는 대표이사의 학계 활동이 JuniMusic의 콘텐츠 전문성을 한층 강화하는 계기가 될 것으로 기대하고 있습니다.', 1, NOW()),
(UUID(), 'NOTICE_PUBLIC', '이도윤 교수, XX대학교 정교수 승진', '이도윤 대표이사 겸 XX대학교 겸임교수가 정교수로 승진했습니다.\n\n이번 승진은 아동 보컬 교육 분야에서의 연구 성과와 강의 활동을 인정받은 결과입니다.\n\n이도윤 교수는 "앞으로도 JuniMusic과 학교 양쪽에서 아이들을 위한 음악 연구를 이어가겠다"고 밝혔습니다.', 1, NOW());
INSERT INTO content (id, type, title, body, isPublished, createdAt) VALUES
(UUID(), 'CAREER', '인사 담당자', '당사 임직원 채용 및 인사 제도 운영을 담당할 인사 담당자를 모집합니다.\n\n담당 업무:\n- 채용 프로세스 기획 및 운영\n- 입사 온보딩 및 근태·노무 관리\n- 사내 인사 제도 운영 지원\n\n자격 요건:\n- 인사 관련 업무 경험 우대\n- 원활한 커뮤니케이션 능력\n\n우대 사항:\n- 소규모 조직 인사 업무 경험자', 1, NOW()),
(UUID(), 'CAREER', '총무 담당자', '사무실 운영 및 행정 업무를 담당할 총무 담당자를 모집합니다.\n\n담당 업무:\n- 사무환경 및 비품 관리\n- 계약서 및 각종 행정 서류 관리\n- 사내 행사 및 지원 업무\n\n자격 요건:\n- 관련 업무 경험 우대\n- 꼼꼼하고 책임감 있는 업무 태도\n\n우대 사항:\n- 소규모 조직 총무 업무 경험자', 1, NOW());
